# Complex PGN. number of matches: 4
def decode_pgn_65284(data_raw: int, data_length_bits: int | None = None) -> NMEA2000Message | None:
    if data_length_bits is None:
        data_length_bits = data_raw.bit_length()
    # maretronProprietaryDcBreakerCurrent | Description: Maretron: Proprietary DC Breaker Current
    if (
        (((data_raw >> 0) & 0x7FF) == 137) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_65284_maretronProprietaryDcBreakerCurrent(data_raw, data_length_bits)
    
    # hondaEngineAlerts | Description: Honda: Engine Alerts
    if (
        (((data_raw >> 0) & 0x7FF) == 257) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_65284_hondaEngineAlerts(data_raw, data_length_bits)
    
    # bepMarineCzoneCircuitStatus | Description: BEP Marine: CZone Circuit Status
    if (
        (((data_raw >> 0) & 0x7FF) == 295) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_65284_bepMarineCzoneCircuitStatus(data_raw, data_length_bits)
    
    # yanmarThrottleControl | Description: Yanmar: Throttle Control
    if (
        (((data_raw >> 0) & 0x7FF) == 172) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_65284_yanmarThrottleControl(data_raw, data_length_bits)
    
    
    return None
    
