def decode_pgn_130819(data_raw: int, data_length_bits: int | None = None) -> NMEA2000Message | None:
    if data_length_bits is None:
        data_length_bits = data_raw.bit_length()
    # simnetRequestReprogram | Description: Simnet: Request Reprogram
    if (
        (((data_raw >> 0) & 0x7FF) == 1857) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_130819_simnetRequestReprogram(data_raw, data_length_bits)
    
    # maretronAlertTransmission | Description: Maretron: Alert Transmission
    if (
        (((data_raw >> 0) & 0x7FF) == 137) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_130819_maretronAlertTransmission(data_raw, data_length_bits)
    
    # webastoHvacCommand | Description: Webasto: HVAC Command
    if (
        (((data_raw >> 0) & 0x7FF) == 540) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_130819_webastoHvacCommand(data_raw, data_length_bits)
    
    # furunoDeadReckoningConfiguration | Description: Furuno: Dead Reckoning Configuration
    if (
        (((data_raw >> 0) & 0x7FF) == 1855) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_130819_furunoDeadReckoningConfiguration(data_raw, data_length_bits)
    
    # bepMarineCzone130819 | Description: BEP Marine: CZone 130819
    if (
        (((data_raw >> 0) & 0x7FF) == 295) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_130819_bepMarineCzone130819(data_raw, data_length_bits)
    
    
    return None
    
