def decode_pgn_130828(data_raw: int, data_length_bits: int | None = None) -> NMEA2000Message | None:
    if data_length_bits is None:
        data_length_bits = data_raw.bit_length()
    # simnetSetSerialNumber | Description: Simnet: Set Serial Number
    if (
        (((data_raw >> 0) & 0x7FF) == 1857) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_130828_simnetSetSerialNumber(data_raw, data_length_bits)
    
    # maretronDometicHvacControlStatus | Description: Maretron: Dometic HVAC Control Status
    if (
        (((data_raw >> 0) & 0x7FF) == 137) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_130828_maretronDometicHvacControlStatus(data_raw, data_length_bits)
    
    # sleipnerDeviceStatusFast | Description: Sleipner: Device Status (Fast)
    if (
        (((data_raw >> 0) & 0x7FF) == 306) and
        (((data_raw >> 13) & 0x7) == 4)
        ):
        return decode_pgn_130828_sleipnerDeviceStatusFast(data_raw, data_length_bits)
    
    
    return None
    
